        plan = generate_plan(problem)

        with PlanValidator(problem_kind=problem.kind) as validator:
            result = validator.validate(problem, plan)
            if str(result.status) != "ValidationResultStatus.VALID":
                print(f"Warning: {task['id']} generated an invalid plan!")

        save_plan(plan, task['plan_output'])
        print(f"Saved plan to {task['plan_output']}")

