from unified_planning.io import PDDLReader
from unified_planning.shortcuts import SequentialPlanValidator, Plan

def load_problem(domain_path, problem_path):
    reader = PDDLReader()
    return reader.parse_problem(domain_path, problem_path)

def load_plan(plan_path, problem):
    reader = PDDLReader()
    return reader.parse_plan(plan_path, problem)

def main():
    with open('problem.json', 'r') as f:
        tasks = json.load(f)

    for task in tasks:
        print(f"Validating {task['id']}...")
        problem = load_problem(task['domain'], task['problem'])

        try:
            plan = load_plan(task['plan_output'], problem)

            with SequentialPlanValidator() as validator:
                result = validator.validate(problem, plan)
                if result.status == unified_planning.engines.ValidationResultStatus.VALID:
                    print(f"{task['id']} is valid!")
                else:
                    print(f"{task['id']} is INVALID: {result.log_messages}")
        except Exception as e:
            print(f"{task['id']} is INVALID due to parsing: {e}")

if __name__ == "__main__":
    main()
