import json
import unified_planning
from unified_planning.io import PDDLReader
from unified_planning.shortcuts import OneshotPlanner

def load_problem(domain_path, problem_path):
    reader = PDDLReader()
    return reader.parse_problem(domain_path, problem_path)

def generate_plan(problem):
    with OneshotPlanner(name="pyperplan") as planner:
        result = planner.solve(problem)
        return result.plan

def save_plan(plan, output_path):
    if plan is None:
        return
    with open(output_path, 'w') as f:
        for action in plan.actions:
            args = " ".join(map(str, action.actual_parameters))
            f.write(f"({action.action.name} {args})\n")

def main():
    with open('problem.json', 'r') as f:
        tasks = json.load(f)

    for task in tasks:
        print(f"Solving {task['id']}...")
        problem = load_problem(task['domain'], task['problem'])
        plan = generate_plan(problem)
        save_plan(plan, task['plan_output'])
        print(f"Saved plan to {task['plan_output']}")

if __name__ == "__main__":
    main()
